    sources: [{ label: 'Card: Quest for Pure Flame (ZEN #144)', url: 'https://scryfall.com/card/zen/144/quest-for-pure-flame' }, { label: 'A Planeswalker\'s Guide to Zendikar: Murasa and Sejiri (2010) — \'The Cipher in Flames\': \'The Glint Pass hides the fabled Cipher in Flames, an ever-burning and complex glyph set in the heart of the rock…\' 바로 뒤에 이 그림(stf79_pureFlame, 설명 없음)', url: 'https://web.archive.org/web/20210917155519/https://magic.wizards.com/en/articles/archive/savor-flavor/planeswalkers-guide-zendikar-murasa-and-sejiri-2010-02-24' }, { label: 'The Moment of Discovery (Savor the Flavor, Doug Beyer, 2009-10-07) — \'and of course all the Quests, Traps, and wondrous locations on land cards contribute to that feel\'', url: 'https://web.archive.org/web/20210122231737/https://magic.wizards.com/en/articles/archive/savor-flavor/moment-discovery-2009-10-07' }],
